[HttpPost]
public IActionResult Submit([FromForm] string name)
{
    // name is populated from the form field named "name"
    return Content($"Hello, {name}");
}

[HttpPost]
public IActionResult Create([FromBody] Product product)
{
    // product is deserialized from the JSON request body
    return Ok(product);
}

[HttpGet]
public IActionResult List([FromQuery] int page, [FromQuery] int pageSize)
{
    // /Products/List?page=2&pageSize=10
    var products = _repository.GetPage(page, pageSize);
    return View(products);
}

[HttpGet("Products/{productId}")]
public IActionResult Details([FromRoute] int productId)
{
    var product = _repository.GetById(productId);
    if (product == null) return NotFound();
    return View(product);
}

[HttpGet]
public IActionResult Log([FromHeader] string requestId)
{
    _logger.LogInformation("Request {RequestId} received", requestId);
    return Ok();
}

public class HomeController : Controller
{
    [HttpPost]
    public IActionResult Places(string[] places)
    {
        // places[0] = "Paris", places[1] = "London", places[2] = "Tokyo"
        return View(places);
    }
}

@model string[]
@{
    ViewData["Title"] = "Places";
}
@if (Model == null || Model.Length == 0)
{
    <form asp-action="Places" method="post">
        @for (int i = 0; i < 3; i++)
        {
            <div class="form-group">
                <label>Place @(i + 1):</label>
                <input name="places" class="form-control" />
            </div>
        }
        <button type="submit" class="btn btn-primary">Submit</button>
    </form>
}
else
{
    <ul>
        @foreach (var place in Model)
        {
            <li>@place</li>
        }
    </ul>
}
